"""Loopback HTTP surface: public recovery endpoints plus authenticated
notification retry and administration endpoints. Every response body is
stable (sorted-key) JSON.
"""
from __future__ import annotations

import json
import re
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from . import db, jsonutil, security, service
from .errors import InvalidRequestError, ServiceError, UnauthorizedError

_ADMIN_ACCOUNT = re.compile(r"^/admin/accounts/(?P<account_id>[^/]+)$")
_ADMIN_ORG_ACCOUNTS = re.compile(r"^/admin/organizations/(?P<organization_id>[^/]+)/accounts$")
_ADMIN_LEASES = re.compile(r"^/admin/queue/leases$")
_ADMIN_LEASE_RELEASE = re.compile(r"^/admin/queue/leases/(?P<attempt_id>\d+)/release$")
_ADMIN_QUEUE_WORKERS = re.compile(r"^/admin/queue/workers$")

# The reclaim endpoint selects purely by recorded lease expiry; a caller
# cannot target it at a specific account or redirect where a notice goes.
_RECLAIM_REJECTED_FIELDS = ("account_id", "recipient", "recipient_email")


class RecoveryServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(
        self,
        address,
        db_path: str,
        bearer_token: str,
        mail_endpoint: str,
        token_ttl_seconds: float = security.TOKEN_TTL_SECONDS,
    ):
        self.db_path = db_path
        self.bearer_token = bearer_token
        self.mail_endpoint = mail_endpoint
        self.token_ttl_seconds = token_ttl_seconds
        super().__init__(address, RecoveryRequestHandler)


class RecoveryRequestHandler(BaseHTTPRequestHandler):
    server: RecoveryServer

    def log_message(self, format, *args):  # noqa: A002 - stdlib signature
        pass  # keep loopback test runs quiet; failures still surface as HTTP errors

    def _read_json_body(self) -> dict:
        length = int(self.headers.get("Content-Length", 0) or 0)
        if length == 0:
            return {}
        raw = self.rfile.read(length)
        if not raw.strip():
            return {}
        try:
            parsed = json.loads(raw)
        except ValueError as exc:
            raise ServiceError("request body is not valid JSON") from exc
        if not isinstance(parsed, dict):
            raise ServiceError("request body must be a JSON object")
        return parsed

    def _require_bearer(self) -> None:
        header = self.headers.get("Authorization", "")
        prefix = "Bearer "
        if not header.startswith(prefix):
            raise UnauthorizedError("missing bearer token")
        supplied = header[len(prefix) :]
        if not security.constant_time_eq(supplied, self.server.bearer_token):
            raise UnauthorizedError("invalid bearer token")

    def _write(self, status: int, payload: dict) -> None:
        body = jsonutil.dumpb(payload)
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _handle(self, dispatch) -> None:
        conn = db.connect(self.server.db_path)
        try:
            status, payload = dispatch(conn)
            self._write(status, payload)
        except ServiceError as exc:
            self._write(exc.http_status, {"error": exc.code, "message": exc.message})
        except Exception as exc:  # pragma: no cover - defensive backstop
            self._write(HTTPStatus.INTERNAL_SERVER_ERROR, {"error": "internal_error", "message": str(exc)})
        finally:
            conn.close()

    def do_POST(self):  # noqa: N802 - required by BaseHTTPRequestHandler
        path = self.path.split("?", 1)[0]

        if path == "/recovery/start":
            def dispatch(conn):
                body = self._read_json_body()
                result = service.start_recovery(
                    conn,
                    body.get("organization"),
                    body.get("email"),
                    self.server.mail_endpoint,
                    ttl_seconds=self.server.token_ttl_seconds,
                )
                return HTTPStatus.OK, result

            return self._handle(dispatch)

        if path == "/recovery/complete":
            def dispatch(conn):
                body = self._read_json_body()
                result = service.complete_recovery(conn, body.get("token"), body.get("mfa_code"))
                return HTTPStatus.OK, result

            return self._handle(dispatch)

        if path == "/recovery/notifications/retry":
            def dispatch(conn):
                self._require_bearer()
                body = self._read_json_body()
                result = service.retry_notifications(
                    conn,
                    self.server.mail_endpoint,
                    batch_size=int(body.get("batch_size", 25)),
                )
                return HTTPStatus.OK, result

            return self._handle(dispatch)

        if path == "/recovery/notification-leases/reclaim":
            def dispatch(conn):
                self._require_bearer()
                body = self._read_json_body()
                rejected = sorted(field for field in _RECLAIM_REJECTED_FIELDS if field in body)
                if rejected:
                    raise InvalidRequestError(
                        f"reclaim does not accept caller-supplied field(s): {', '.join(rejected)}"
                    )
                result = service.reclaim_expired_notification_leases(
                    conn,
                    worker_id=body.get("worker_id"),
                    batch_size=int(body.get("batch_size", 25)),
                )
                return HTTPStatus.OK, result

            return self._handle(dispatch)

        if path == "/recovery/notification-leases/cleanup-stale-owners":
            def dispatch(conn):
                self._require_bearer()
                body = self._read_json_body()
                result = service.cleanup_stale_lease_owners(
                    conn,
                    batch_size=int(body.get("batch_size", 25)),
                )
                return HTTPStatus.OK, result

            return self._handle(dispatch)

        match = _ADMIN_LEASE_RELEASE.match(path)
        if match:
            def dispatch(conn):
                self._require_bearer()
                result = service.admin_release_lease(conn, int(match.group("attempt_id")))
                return HTTPStatus.OK, result

            return self._handle(dispatch)

        self._write(HTTPStatus.NOT_FOUND, {"error": "not_found", "message": f"no route for POST {path}"})

    def do_GET(self):  # noqa: N802 - required by BaseHTTPRequestHandler
        path = self.path.split("?", 1)[0]

        match = _ADMIN_ACCOUNT.match(path)
        if match:
            def dispatch(conn):
                self._require_bearer()
                result = service.show_account(conn, match.group("account_id"))
                return HTTPStatus.OK, result

            return self._handle(dispatch)

        match = _ADMIN_ORG_ACCOUNTS.match(path)
        if match:
            def dispatch(conn):
                self._require_bearer()
                result = service.list_accounts(conn, match.group("organization_id"))
                return HTTPStatus.OK, result

            return self._handle(dispatch)

        if _ADMIN_LEASES.match(path):
            def dispatch(conn):
                self._require_bearer()
                result = service.admin_list_leases(conn)
                return HTTPStatus.OK, result

            return self._handle(dispatch)

        if _ADMIN_QUEUE_WORKERS.match(path):
            def dispatch(conn):
                self._require_bearer()
                result = service.worker_status(conn)
                return HTTPStatus.OK, result

            return self._handle(dispatch)

        self._write(HTTPStatus.NOT_FOUND, {"error": "not_found", "message": f"no route for GET {path}"})


def create_server(
    host: str,
    port: int,
    db_path: str,
    bearer_token: str,
    mail_endpoint: str,
    token_ttl_seconds: float = security.TOKEN_TTL_SECONDS,
) -> RecoveryServer:
    return RecoveryServer((host, port), db_path, bearer_token, mail_endpoint, token_ttl_seconds)

"""Business logic tying storage, mail delivery, and the retry queue together.

Every function accepts an explicit `now` (epoch seconds, defaulting to the
real clock) so tests can drive expiry and lease behavior deterministically.
"""
from __future__ import annotations

import sqlite3
from typing import Any

from . import clock, mail, notice, security, store
from .errors import (
    InvalidRequestError,
    InvalidTokenError,
    MfaInvalidError,
    MfaRequiredError,
    NotFoundError,
)


# -- account administration --------------------------------------------------


def create_account(conn: sqlite3.Connection, organization_id: str, account_id: str, email: str, now: float | None = None) -> dict[str, Any]:
    now = clock.now() if now is None else now
    if not organization_id or not account_id or not email:
        raise InvalidRequestError("organization_id, account_id, and email are required")
    store.create_account(conn, account_id, organization_id, email, now)
    return show_account(conn, account_id)


def change_email(conn: sqlite3.Connection, account_id: str, new_email: str, now: float | None = None) -> dict[str, Any]:
    now = clock.now() if now is None else now
    if not new_email:
        raise InvalidRequestError("new_email is required")
    store.change_email(conn, account_id, new_email, now)
    return show_account(conn, account_id)


def show_account(conn: sqlite3.Connection, account_id: str) -> dict[str, Any]:
    account = store.require_account(conn, account_id)
    history = [
        {
            "email": row["email"],
            "effective_from": row["effective_from"],
            "released_at": row["released_at"],
        }
        for row in store.get_email_history(conn, account_id)
    ]
    mfa = store.get_confirmed_mfa(conn, account_id)
    return {
        "account_id": account["id"],
        "organization_id": account["organization_id"],
        "current_email": account["current_email"],
        "created_at": account["created_at"],
        "updated_at": account["updated_at"],
        "mfa_enrolled": mfa is not None,
        "email_history": history,
    }


def list_accounts(conn: sqlite3.Connection, organization_id: str) -> dict[str, Any]:
    rows = store.list_accounts(conn, organization_id)
    return {"organization_id": organization_id, "accounts": [show_account(conn, row["id"]) for row in rows]}


def enroll_mfa(conn: sqlite3.Connection, account_id: str, now: float | None = None) -> dict[str, Any]:
    now = clock.now() if now is None else now
    account = store.require_account(conn, account_id)
    secret = security.generate_totp_secret()
    store.enroll_mfa(conn, account_id, secret, now)
    return {
        "account_id": account_id,
        "secret": secret,
        "otpauth_uri": security.otpauth_uri(secret, account_id, account["organization_id"]),
    }


# -- recovery flow ------------------------------------------------------------


def start_recovery(
    conn: sqlite3.Connection,
    organization_id: str,
    email: str,
    mail_endpoint: str,
    now: float | None = None,
    ttl_seconds: float = security.TOKEN_TTL_SECONDS,
) -> dict[str, Any]:
    now = clock.now() if now is None else now
    if not organization_id or not email:
        raise InvalidRequestError("organization and email are required")
    account = store.find_account_by_current_email(conn, organization_id, email)
    if account is None:
        raise NotFoundError("no account matches that organization and email")

    request_id = security.generate_request_id()
    token = security.generate_token()
    store.create_recovery_request(
        conn, request_id, organization_id, account["id"], token, now, ttl_seconds
    )
    attempt_id = store.create_notification_attempt(conn, request_id, account["id"], attempt_number=1, now=now)
    delivery_status = _attempt_delivery(conn, attempt_id, account["id"], token, mail_endpoint, now)
    return {"request_id": request_id, "status": delivery_status}


def _attempt_delivery(
    conn: sqlite3.Connection, attempt_id: int, account_id: str, token: str, mail_endpoint: str, now: float
) -> str:
    account = store.require_account(conn, account_id)
    recipient = account["current_email"]
    result = mail.send(mail_endpoint, recipient=recipient, recovery_token=token)
    if result.success:
        store.mark_attempt_sent(conn, attempt_id, recipient, result.receipt, now)
        return "sent"

    locator = notice.encode_retry_locator(result.receipt or "", account_id)
    if result.receipt:
        # The starter locator drops the receipt, so keep it in front of the
        # saved value; a reloaded notice can then name the attempt that failed.
        locator = f"{result.receipt}|{locator}"
    store.mark_attempt_retry_pending(conn, attempt_id, recipient, result.receipt, locator, result.error, now)
    return "queued_retry"


def complete_recovery(
    conn: sqlite3.Connection, token: str, mfa_code: str | None = None, now: float | None = None
) -> dict[str, Any]:
    now = clock.now() if now is None else now
    if not token:
        raise InvalidRequestError("token is required")
    request = store.find_pending_request_by_token(conn, token)
    if request is None or request["expires_at"] < now:
        raise InvalidTokenError("recovery token is invalid, expired, or already used")

    account = store.require_account(conn, request["account_id"])
    mfa = store.get_confirmed_mfa(conn, account["id"])
    if mfa is not None:
        if not mfa_code:
            raise MfaRequiredError("this account requires an MFA code to complete recovery")
        if not security.verify_totp(mfa["secret"], mfa_code, now):
            raise MfaInvalidError("the provided MFA code is invalid")

    completed = store.mark_request_completed(conn, request["id"], now)
    if not completed:
        raise InvalidTokenError("recovery token is invalid, expired, or already used")

    return {
        "request_id": request["id"],
        "status": "completed",
        "account_id": account["id"],
        "organization_id": account["organization_id"],
    }


# -- notification retry queue -------------------------------------------------


def retry_notifications(
    conn: sqlite3.Connection,
    mail_endpoint: str,
    now: float | None = None,
    lease_seconds: float = security.LEASE_SECONDS,
    batch_size: int = 25,
    worker_id: str | None = None,
) -> dict[str, Any]:
    now = clock.now() if now is None else now
    worker_id = worker_id or security.generate_lease_owner()
    results = []

    for attempt in store.find_retryable_attempts(conn, now, batch_size):
        lease = store.claim_lease(conn, attempt["id"], worker_id, now, lease_seconds)
        if lease is None:
            continue  # another worker already reclaimed this lease
        try:
            outcome = _process_retry(conn, attempt, mail_endpoint, now)
        finally:
            store.release_lease(conn, attempt["id"], worker_id, lease["generation"], now)
        results.append(outcome)

    return {"processed": len(results), "results": results}


def _process_retry(conn: sqlite3.Connection, attempt: sqlite3.Row, mail_endpoint: str, now: float) -> dict[str, Any]:
    request = store.get_recovery_request(conn, attempt["request_id"])
    account_id = notice.account_id_from_retry_locator(attempt["retry_locator"], attempt["account_id"])

    if request is None or request["status"] != "pending" or request["expires_at"] < now:
        store.mark_attempt_abandoned(conn, attempt["id"], "recovery_request_no_longer_pending", now)
        return {"attempt_id": attempt["id"], "request_id": attempt["request_id"], "outcome": "abandoned"}

    account = store.get_account(conn, account_id)
    if account is None:
        store.mark_attempt_abandoned(conn, attempt["id"], "account_not_found", now)
        return {"attempt_id": attempt["id"], "request_id": attempt["request_id"], "outcome": "abandoned"}

    recipient = account["current_email"]
    result = mail.send(mail_endpoint, recipient=recipient, recovery_token=request["token"])
    if result.success:
        store.mark_attempt_sent(conn, attempt["id"], recipient, result.receipt, now)
        return {"attempt_id": attempt["id"], "request_id": attempt["request_id"], "outcome": "sent"}

    next_attempt_number = attempt["attempt_number"] + 1
    if next_attempt_number > security.MAX_NOTIFICATION_ATTEMPTS:
        store.mark_attempt_terminal(conn, attempt["id"], result.error, now)
        return {"attempt_id": attempt["id"], "request_id": attempt["request_id"], "outcome": "failed_terminal"}

    locator = notice.encode_retry_locator(result.receipt or "", account_id)
    store.bump_attempt_number(conn, attempt["id"], next_attempt_number, now)
    store.mark_attempt_retry_pending(conn, attempt["id"], recipient, result.receipt, locator, result.error, now)
    return {"attempt_id": attempt["id"], "request_id": attempt["request_id"], "outcome": "queued_retry"}


def _require_bounded_batch_size(batch_size: int) -> None:
    if isinstance(batch_size, bool) or not isinstance(batch_size, int) or not (
        1 <= batch_size <= security.MAX_RECLAIM_BATCH_SIZE
    ):
        raise InvalidRequestError(
            f"batch_size must be an integer between 1 and {security.MAX_RECLAIM_BATCH_SIZE}"
        )


def reclaim_expired_notification_leases(
    conn: sqlite3.Connection,
    now: float | None = None,
    worker_id: str | None = None,
    lease_seconds: float = security.LEASE_SECONDS,
    batch_size: int = 25,
) -> dict[str, Any]:
    """Reclaim leases whose recorded expiry has passed and stage them for `worker_id`.

    Only attempts already past their lease's `leased_until` are eligible --
    an attempt that was never leased, or whose lease was released early, is
    left for the normal retry path. The fenced `claim_lease` guard means that
    when two callers race for the same expired lease, only one succeeds; the
    loser simply does not see that attempt in its `reclaimed` list. Reclaiming
    never reads or accepts an account id or recipient from the caller -- the
    notification's delivery authority stays whatever was bound when the
    attempt was created.

    The batch is bounded (`security.MAX_RECLAIM_BATCH_SIZE`) so a caller
    cannot force an unbounded scan-and-mutate pass in one request. Each
    successful reclaim commits its lease mutation together with a "renewal"
    audit event in a single SQLite transaction (`store.reclaim_lease_and_record_renewal`),
    so the two either both land or neither does.
    """
    now = clock.now() if now is None else now
    _require_bounded_batch_size(batch_size)
    worker_id = worker_id or security.generate_lease_owner()
    reclaimed = []
    for attempt in store.find_expired_leases(conn, now, batch_size):
        lease = store.reclaim_lease_and_record_renewal(conn, attempt["id"], worker_id, now, lease_seconds)
        if lease is None:
            continue  # another worker reclaimed this lease first
        reclaimed.append(
            {
                "notification_attempt_id": attempt["id"],
                "request_id": attempt["request_id"],
                "lease_owner": lease["lease_owner"],
                "generation": lease["generation"],
                "leased_until": lease["leased_until"],
            }
        )
    return {"worker_id": worker_id, "reclaimed": reclaimed, "count": len(reclaimed)}


def cleanup_stale_lease_owners(
    conn: sqlite3.Connection,
    now: float | None = None,
    batch_size: int = 25,
) -> dict[str, Any]:
    """Force-release leases whose recorded expiry has passed, without
    reassigning them to a specific worker.

    This is the maintenance counterpart to reclaim: reclaim stages an
    expired lease for the caller to work on right away, while cleanup simply
    clears a stale owner's hold and returns the attempt to the general retry
    pool for the next `retry_notifications` batch to pick up. Uses the same
    bounded-batch selection as reclaim, and commits each release together
    with a "stale_cleanup" audit event in a single transaction
    (`store.release_stale_lease_and_record_cleanup`).
    """
    now = clock.now() if now is None else now
    _require_bounded_batch_size(batch_size)
    cleaned = []
    for attempt in store.find_expired_leases(conn, now, batch_size):
        lease = store.release_stale_lease_and_record_cleanup(conn, attempt["id"], now)
        if lease is None:
            continue  # no longer eligible by the time this ran
        cleaned.append(
            {
                "notification_attempt_id": attempt["id"],
                "request_id": attempt["request_id"],
                "stale_owner": lease["lease_owner"],
                "generation": lease["generation"],
            }
        )
    return {"cleaned": cleaned, "count": len(cleaned)}


def worker_status(conn: sqlite3.Connection, now: float | None = None) -> dict[str, Any]:
    """Per-worker rollup of currently-held leases, including how many of a
    worker's held leases are already stale (past `leased_until`).
    """
    now = clock.now() if now is None else now
    workers = [
        {
            "lease_owner": row["lease_owner"],
            "held_leases": row["held_leases"],
            "stale_leases": row["stale_leases"],
            "most_recent_leased_at": row["most_recent_leased_at"],
        }
        for row in store.worker_lease_summary(conn, now)
    ]
    return {"workers": workers, "generated_at": now}


# -- admin ---------------------------------------------------------------


def admin_list_leases(conn: sqlite3.Connection, now: float | None = None) -> dict[str, Any]:
    now = clock.now() if now is None else now
    leases = []
    for row in store.list_leases(conn):
        leases.append(
            {
                "notification_attempt_id": row["notification_attempt_id"],
                "request_id": row["request_id"],
                "attempt_status": row["attempt_status"],
                "lease_owner": row["lease_owner"],
                "leased_at": row["leased_at"],
                "leased_until": row["leased_until"],
                "released_at": row["released_at"],
                "expired": row["released_at"] is None and row["leased_until"] < now,
            }
        )
    return {"leases": leases}


def admin_release_lease(conn: sqlite3.Connection, attempt_id: int, now: float | None = None) -> dict[str, Any]:
    now = clock.now() if now is None else now
    lease = store.get_lease(conn, attempt_id)
    if lease is None:
        raise NotFoundError(f"no lease for notification attempt {attempt_id}")
    store.admin_release_lease(conn, attempt_id, now)
    return {"notification_attempt_id": attempt_id, "released": True}

"""SQL-backed persistence for organizations, accounts, MFA, recovery
requests, notification attempts, and queue leases.

Every function takes an open connection explicitly rather than owning one,
so the HTTP layer can use a short-lived connection per request while the CLI
and tests can share a single connection.
"""
from __future__ import annotations

import sqlite3
from typing import Any

from . import clock
from .errors import ConflictError, NotFoundError

# -- organizations -----------------------------------------------------


def get_or_create_organization(conn: sqlite3.Connection, organization_id: str, now: float) -> None:
    conn.execute(
        "INSERT INTO organizations (id, created_at) VALUES (?, ?) "
        "ON CONFLICT(id) DO NOTHING",
        (organization_id, clock.iso(now)),
    )


# -- accounts ------------------------------------------------------------


def create_account(
    conn: sqlite3.Connection, account_id: str, organization_id: str, email: str, now: float
) -> None:
    ts = clock.iso(now)
    conn.execute("BEGIN IMMEDIATE")
    try:
        if conn.execute("SELECT 1 FROM accounts WHERE id = ?", (account_id,)).fetchone():
            raise ConflictError(f"account {account_id!r} already exists")
        if conn.execute(
            "SELECT 1 FROM accounts WHERE organization_id = ? AND current_email = ?",
            (organization_id, email),
        ).fetchone():
            raise ConflictError(f"email {email!r} is already in use in this organization")
        get_or_create_organization(conn, organization_id, now)
        conn.execute(
            "INSERT INTO accounts (id, organization_id, current_email, created_at, updated_at) "
            "VALUES (?, ?, ?, ?, ?)",
            (account_id, organization_id, email, ts, ts),
        )
        conn.execute(
            "INSERT INTO email_history (organization_id, account_id, email, effective_from, released_at) "
            "VALUES (?, ?, ?, ?, NULL)",
            (organization_id, account_id, email, ts),
        )
        conn.execute("COMMIT")
    except Exception:
        conn.execute("ROLLBACK")
        raise


def get_account(conn: sqlite3.Connection, account_id: str) -> sqlite3.Row | None:
    return conn.execute("SELECT * FROM accounts WHERE id = ?", (account_id,)).fetchone()


def require_account(conn: sqlite3.Connection, account_id: str) -> sqlite3.Row:
    row = get_account(conn, account_id)
    if row is None:
        raise NotFoundError(f"account {account_id!r} not found")
    return row


def find_account_by_current_email(
    conn: sqlite3.Connection, organization_id: str, email: str
) -> sqlite3.Row | None:
    return conn.execute(
        "SELECT * FROM accounts WHERE organization_id = ? AND current_email = ?",
        (organization_id, email),
    ).fetchone()


def list_accounts(conn: sqlite3.Connection, organization_id: str) -> list[sqlite3.Row]:
    return conn.execute(
        "SELECT * FROM accounts WHERE organization_id = ? ORDER BY id", (organization_id,)
    ).fetchall()


def change_email(conn: sqlite3.Connection, account_id: str, new_email: str, now: float) -> None:
    ts = clock.iso(now)
    conn.execute("BEGIN IMMEDIATE")
    try:
        account = conn.execute("SELECT * FROM accounts WHERE id = ?", (account_id,)).fetchone()
        if account is None:
            raise NotFoundError(f"account {account_id!r} not found")
        if account["current_email"] == new_email:
            conn.execute("COMMIT")
            return
        clash = conn.execute(
            "SELECT 1 FROM accounts WHERE organization_id = ? AND current_email = ? AND id != ?",
            (account["organization_id"], new_email, account_id),
        ).fetchone()
        if clash:
            raise ConflictError(f"email {new_email!r} is already in use in this organization")
        conn.execute(
            "UPDATE email_history SET released_at = ? "
            "WHERE account_id = ? AND email = ? AND released_at IS NULL",
            (ts, account_id, account["current_email"]),
        )
        conn.execute(
            "UPDATE accounts SET current_email = ?, updated_at = ? WHERE id = ?",
            (new_email, ts, account_id),
        )
        conn.execute(
            "INSERT INTO email_history (organization_id, account_id, email, effective_from, released_at) "
            "VALUES (?, ?, ?, ?, NULL)",
            (account["organization_id"], account_id, new_email, ts),
        )
        conn.execute("COMMIT")
    except Exception:
        conn.execute("ROLLBACK")
        raise


def get_email_history(conn: sqlite3.Connection, account_id: str) -> list[sqlite3.Row]:
    return conn.execute(
        "SELECT * FROM email_history WHERE account_id = ? ORDER BY id", (account_id,)
    ).fetchall()


# -- MFA -------------------------------------------------------------------


def enroll_mfa(conn: sqlite3.Connection, account_id: str, secret: str, now: float, factor_type: str = "totp") -> None:
    ts = clock.iso(now)
    conn.execute(
        "INSERT INTO mfa_factors (account_id, factor_type, secret, created_at, confirmed_at) "
        "VALUES (?, ?, ?, ?, ?) "
        "ON CONFLICT(account_id, factor_type) DO UPDATE SET secret = excluded.secret, "
        "created_at = excluded.created_at, confirmed_at = excluded.confirmed_at",
        (account_id, factor_type, secret, ts, ts),
    )


def get_confirmed_mfa(conn: sqlite3.Connection, account_id: str, factor_type: str = "totp") -> sqlite3.Row | None:
    return conn.execute(
        "SELECT * FROM mfa_factors WHERE account_id = ? AND factor_type = ? AND confirmed_at IS NOT NULL",
        (account_id, factor_type),
    ).fetchone()


# -- recovery requests -------------------------------------------------------


def create_recovery_request(
    conn: sqlite3.Connection,
    request_id: str,
    organization_id: str,
    account_id: str,
    token: str,
    now: float,
    ttl_seconds: float,
) -> None:
    conn.execute(
        "INSERT INTO recovery_requests "
        "(id, organization_id, account_id, token, status, created_at, expires_at, completed_at) "
        "VALUES (?, ?, ?, ?, 'pending', ?, ?, NULL)",
        (request_id, organization_id, account_id, token, clock.iso(now), now + ttl_seconds),
    )


def get_recovery_request(conn: sqlite3.Connection, request_id: str) -> sqlite3.Row | None:
    return conn.execute("SELECT * FROM recovery_requests WHERE id = ?", (request_id,)).fetchone()


def find_pending_request_by_token(conn: sqlite3.Connection, token: str) -> sqlite3.Row | None:
    return conn.execute(
        "SELECT * FROM recovery_requests WHERE token = ? AND status = 'pending'", (token,)
    ).fetchone()


def mark_request_completed(conn: sqlite3.Connection, request_id: str, now: float) -> bool:
    cur = conn.execute(
        "UPDATE recovery_requests SET status = 'completed', completed_at = ? "
        "WHERE id = ? AND status = 'pending' AND expires_at >= ?",
        (clock.iso(now), request_id, now),
    )
    return cur.rowcount == 1


# -- notification attempts ---------------------------------------------------


def create_notification_attempt(
    conn: sqlite3.Connection,
    request_id: str,
    account_id: str,
    attempt_number: int,
    now: float,
) -> int:
    ts = clock.iso(now)
    cur = conn.execute(
        "INSERT INTO notification_attempts "
        "(request_id, account_id, attempt_number, status, recipient_email, provider_receipt, "
        " retry_locator, last_error, created_at, updated_at) "
        "VALUES (?, ?, ?, 'in_progress', NULL, NULL, NULL, NULL, ?, ?)",
        (request_id, account_id, attempt_number, ts, ts),
    )
    return cur.lastrowid


def mark_attempt_sent(conn: sqlite3.Connection, attempt_id: int, recipient: str, provider_receipt: str | None, now: float) -> None:
    conn.execute(
        "UPDATE notification_attempts SET status = 'sent', recipient_email = ?, "
        "provider_receipt = ?, last_error = NULL, updated_at = ? WHERE id = ?",
        (recipient, provider_receipt, clock.iso(now), attempt_id),
    )


def mark_attempt_retry_pending(
    conn: sqlite3.Connection,
    attempt_id: int,
    recipient: str,
    provider_receipt: str | None,
    retry_locator: str,
    error: str | None,
    now: float,
) -> None:
    conn.execute(
        "UPDATE notification_attempts SET status = 'retry_pending', recipient_email = ?, "
        "provider_receipt = ?, retry_locator = ?, last_error = ?, updated_at = ? WHERE id = ?",
        (recipient, provider_receipt, retry_locator, error, clock.iso(now), attempt_id),
    )


def mark_attempt_terminal(conn: sqlite3.Connection, attempt_id: int, error: str | None, now: float) -> None:
    conn.execute(
        "UPDATE notification_attempts SET status = 'failed_terminal', last_error = ?, updated_at = ? WHERE id = ?",
        (error, clock.iso(now), attempt_id),
    )


def mark_attempt_abandoned(conn: sqlite3.Connection, attempt_id: int, reason: str, now: float) -> None:
    conn.execute(
        "UPDATE notification_attempts SET status = 'abandoned', last_error = ?, updated_at = ? WHERE id = ?",
        (reason, clock.iso(now), attempt_id),
    )


def bump_attempt_number(conn: sqlite3.Connection, attempt_id: int, attempt_number: int, now: float) -> None:
    conn.execute(
        "UPDATE notification_attempts SET attempt_number = ?, updated_at = ? WHERE id = ?",
        (attempt_number, clock.iso(now), attempt_id),
    )


def get_notification_attempt(conn: sqlite3.Connection, attempt_id: int) -> sqlite3.Row | None:
    return conn.execute("SELECT * FROM notification_attempts WHERE id = ?", (attempt_id,)).fetchone()


def find_retryable_attempts(conn: sqlite3.Connection, now: float, limit: int) -> list[sqlite3.Row]:
    return conn.execute(
        "SELECT na.* FROM notification_attempts na "
        "LEFT JOIN queue_leases ql ON ql.notification_attempt_id = na.id "
        "WHERE na.status = 'retry_pending' "
        "AND (ql.id IS NULL OR ql.released_at IS NOT NULL OR ql.leased_until < ?) "
        "ORDER BY na.created_at LIMIT ?",
        (now, limit),
    ).fetchall()


def find_expired_leases(conn: sqlite3.Connection, now: float, limit: int) -> list[sqlite3.Row]:
    """Retryable attempts still held under a lease whose recorded expiry has passed.

    Unlike `find_retryable_attempts`, this excludes attempts that were never
    leased and leases that were already released early -- it only surfaces
    leases abandoned by a worker that stopped renewing before `leased_until`.
    """
    return conn.execute(
        "SELECT na.* FROM notification_attempts na "
        "JOIN queue_leases ql ON ql.notification_attempt_id = na.id "
        "WHERE na.status = 'retry_pending' "
        "AND ql.released_at IS NULL AND ql.leased_until < ? "
        "ORDER BY na.created_at LIMIT ?",
        (now, limit),
    ).fetchall()


# -- queue leases --------------------------------------------------------


def claim_lease(
    conn: sqlite3.Connection, attempt_id: int, owner: str, now: float, lease_seconds: float
) -> sqlite3.Row | None:
    """Claim an attempt's lease for `owner`, bumping its generation.

    Succeeds only if the lease is unheld (first claim), released, or expired,
    so an active lease can never move to a different owner out from under
    whoever currently holds it. The returned row's `generation` is the
    fencing token the caller must present to `renew_lease`/`release_lease`.
    """
    cur = conn.execute(
        "INSERT INTO queue_leases "
        "(notification_attempt_id, lease_owner, generation, leased_at, leased_until, released_at) "
        "VALUES (?, ?, 1, ?, ?, NULL) "
        "ON CONFLICT(notification_attempt_id) DO UPDATE SET "
        "lease_owner = excluded.lease_owner, "
        "generation = queue_leases.generation + 1, "
        "leased_at = excluded.leased_at, "
        "leased_until = excluded.leased_until, "
        "released_at = NULL "
        "WHERE queue_leases.released_at IS NOT NULL OR queue_leases.leased_until < ?",
        (attempt_id, owner, now, now + lease_seconds, now),
    )
    if cur.rowcount != 1:
        return None
    return get_lease(conn, attempt_id)


def renew_lease(
    conn: sqlite3.Connection,
    attempt_id: int,
    owner: str,
    generation: int,
    now: float,
    lease_seconds: float,
) -> sqlite3.Row | None:
    """Extend an unexpired lease still held by (owner, generation)."""
    cur = conn.execute(
        "UPDATE queue_leases SET leased_until = ? "
        "WHERE notification_attempt_id = ? AND lease_owner = ? AND generation = ? "
        "AND released_at IS NULL AND leased_until >= ?",
        (now + lease_seconds, attempt_id, owner, generation, now),
    )
    if cur.rowcount != 1:
        return None
    return get_lease(conn, attempt_id)


def release_lease(conn: sqlite3.Connection, attempt_id: int, owner: str, generation: int, now: float) -> bool:
    """Release a lease still held by (owner, generation)."""
    cur = conn.execute(
        "UPDATE queue_leases SET released_at = ? "
        "WHERE notification_attempt_id = ? AND lease_owner = ? AND generation = ? AND released_at IS NULL",
        (now, attempt_id, owner, generation),
    )
    return cur.rowcount == 1


def admin_release_lease(conn: sqlite3.Connection, attempt_id: int, now: float) -> bool:
    """Force-release a lease regardless of current owner/generation."""
    cur = conn.execute(
        "UPDATE queue_leases SET released_at = ? WHERE notification_attempt_id = ? AND released_at IS NULL",
        (now, attempt_id),
    )
    return cur.rowcount == 1


def get_lease(conn: sqlite3.Connection, attempt_id: int) -> sqlite3.Row | None:
    return conn.execute(
        "SELECT * FROM queue_leases WHERE notification_attempt_id = ?", (attempt_id,)
    ).fetchone()


def list_leases(conn: sqlite3.Connection) -> list[sqlite3.Row]:
    return conn.execute(
        "SELECT ql.*, na.status AS attempt_status, na.request_id AS request_id "
        "FROM queue_leases ql JOIN notification_attempts na ON na.id = ql.notification_attempt_id "
        "ORDER BY ql.id"
    ).fetchall()


def worker_lease_summary(conn: sqlite3.Connection, now: float) -> list[sqlite3.Row]:
    """Per-owner rollup of currently-held leases, for worker status reporting."""
    return conn.execute(
        "SELECT lease_owner, "
        "COUNT(*) AS held_leases, "
        "SUM(CASE WHEN leased_until < ? THEN 1 ELSE 0 END) AS stale_leases, "
        "MAX(leased_at) AS most_recent_leased_at "
        "FROM queue_leases WHERE released_at IS NULL "
        "GROUP BY lease_owner ORDER BY lease_owner",
        (now,),
    ).fetchall()


# -- lease audit log -------------------------------------------------------


def record_lease_audit_event(
    conn: sqlite3.Connection,
    attempt_id: int,
    event_type: str,
    lease_owner: str,
    generation: int,
    now: float,
    previous_owner: str | None = None,
) -> None:
    """Append a structured lease lifecycle event.

    Only the attempt id, the owners involved, the generation, and a
    timestamp are recorded. There is no free-text field, so a recovery
    token (or any other secret) can never be written into this table.
    """
    conn.execute(
        "INSERT INTO lease_audit_events "
        "(notification_attempt_id, event_type, previous_owner, lease_owner, generation, occurred_at) "
        "VALUES (?, ?, ?, ?, ?, ?)",
        (attempt_id, event_type, previous_owner, lease_owner, generation, now),
    )


def list_lease_audit_events(conn: sqlite3.Connection, attempt_id: int | None = None) -> list[sqlite3.Row]:
    if attempt_id is None:
        return conn.execute("SELECT * FROM lease_audit_events ORDER BY id").fetchall()
    return conn.execute(
        "SELECT * FROM lease_audit_events WHERE notification_attempt_id = ? ORDER BY id",
        (attempt_id,),
    ).fetchall()


def reclaim_lease_and_record_renewal(
    conn: sqlite3.Connection, attempt_id: int, owner: str, now: float, lease_seconds: float
) -> sqlite3.Row | None:
    """Claim an expired lease for `owner` and record the renewal audit event
    in one transaction, so the lease mutation and the notice's staging
    record either both land or neither does.

    Returns None (with nothing written) if the lease was no longer eligible
    for reclaim by the time this ran, e.g. another worker reclaimed it first.
    """
    conn.execute("BEGIN IMMEDIATE")
    try:
        previous = get_lease(conn, attempt_id)
        previous_owner = previous["lease_owner"] if previous is not None else None
        lease = claim_lease(conn, attempt_id, owner, now, lease_seconds)
        if lease is None:
            conn.execute("ROLLBACK")
            return None
        record_lease_audit_event(
            conn, attempt_id, "renewal", lease["lease_owner"], lease["generation"], now,
            previous_owner=previous_owner,
        )
        conn.execute("COMMIT")
        return lease
    except Exception:
        conn.execute("ROLLBACK")
        raise


def release_stale_lease_and_record_cleanup(
    conn: sqlite3.Connection, attempt_id: int, now: float
) -> sqlite3.Row | None:
    """Force-release a lease still held by a stale (expired) owner and record
    the cleanup audit event in one transaction.

    Unlike reclaim, this does not reassign the lease to a new owner -- it
    only clears the stale owner's hold so the attempt returns to the general
    retry pool. Re-checks that the lease is still expired under the write
    lock this transaction holds, so a lease renewed or reclaimed between
    selection and this call is left untouched.
    """
    conn.execute("BEGIN IMMEDIATE")
    try:
        lease = get_lease(conn, attempt_id)
        if lease is None or lease["released_at"] is not None or lease["leased_until"] >= now:
            conn.execute("ROLLBACK")
            return None
        released = admin_release_lease(conn, attempt_id, now)
        if not released:
            conn.execute("ROLLBACK")
            return None
        record_lease_audit_event(
            conn, attempt_id, "stale_cleanup", lease["lease_owner"], lease["generation"], now,
            previous_owner=None,
        )
        conn.execute("COMMIT")
        return lease
    except Exception:
        conn.execute("ROLLBACK")
        raise


def to_dict(row: sqlite3.Row | None) -> dict[str, Any] | None:
    return dict(row) if row is not None else None

"""Time helpers. Callers may inject an explicit epoch to keep tests deterministic."""
from __future__ import annotations

import time
from datetime import datetime, timezone


def now() -> float:
